CREATE VIEW bookkeeper.general_ledger AS
 SELECT l.id AS line_id,
    e.entry_date,
    l.account_number,
    l.debit,
    l.credit,
    l.currency,
    e.description
   FROM (bookkeeper.journal_lines l
     JOIN bookkeeper.journal_entries e ON ((l.journal_entry_id = e.id)))
  WHERE ((e.status)::text = 'POSTED'::text);


